INSERT  IGNORE INTO `user_roles` VALUES (1,'admin','Administrator','Full access to all features','[\"*\"]','2026-05-01 05:26:42'),(2,'manager','Manager','Can manage servers and clients','[\"servers.view\", \"servers.create\", \"servers.edit\", \"clients.view\", \"clients.create\", \"clients.edit\", \"clients.delete\"]','2026-05-01 05:26:42'),(3,'viewer','Viewer','Can only view own clients','[\"clients.view_own\", \"clients.download_own\"]','2026-05-01 05:26:42');
INSERT  IGNORE INTO `protocols` VALUES (11,'AmneziaWG 2.0','awg2','AmneziaWG 2.0 — userspace Go implementation (amneziawg-go). No kernel module required.','{\"engine\": \"shell\", \"metadata\": {\"interface\": \"awg0\", \"config_dir\": \"/opt/amnezia/awg2\", \"port_range\": [30000, 65000], \"vpn_subnet\": \"10.8.1.0/24\", \"config_file\": \"awg0.conf\", \"container_name\": \"amnezia-awg2\"}}','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${SERVER_CONTAINER:-amnezia-awg2}\"\nPORT_RANGE_START=${PORT_RANGE_START:-30000}\nPORT_RANGE_END=${PORT_RANGE_END:-65000}\nVPN_PORT=\"${SERVER_PORT:-443}\"\nMTU=${MTU:-1280}\nHOST_CONFIG_DIR=\"/opt/amnezia/awg2\"\nCONTAINER_CONFIG_DIR=\"/opt/amnezia/awg\"\nCONFIG_FILE=\"awg0.conf\"\n\nrand_between() {\n  local min=\"$1\"\n  local max=\"$2\"\n  echo $((min + RANDOM % (max - min + 1)))\n}\n\nrand_u31() {\n  echo $((((RANDOM << 16) | RANDOM) & 2147483647))\n}\n\nrand_h_range() {\n  local start\n  local finish\n  start=$(rand_u31)\n  if [ \"$start\" -lt 100000000 ]; then\n    start=$((start + 100000000))\n  fi\n  if [ \"$start\" -gt 2146000000 ]; then\n    start=$((start - 100000000))\n  fi\n  finish=$((start + $(rand_between 10000 900000)))\n  if [ \"$finish\" -gt 2147483647 ]; then\n    finish=2147483647\n  fi\n  echo \"${start}-${finish}\"\n}\n\nJC=${JC:-$(rand_between 4 12)}\nJMIN=${JMIN:-$(rand_between 8 64)}\nJMAX=${JMAX:-$(rand_between 80 512)}\nif [ \"$JMAX\" -le \"$JMIN\" ]; then\n  JMAX=$((JMIN + 32))\nfi\nS1_VAL=${S1_VAL:-$(rand_between 15 150)}\nS2_VAL=${S2_VAL:-$(rand_between 15 150)}\nif [ \"$((S1_VAL + 56))\" -eq \"$S2_VAL\" ]; then\n  S2_VAL=$((S2_VAL + 1))\nfi\nS3_VAL=${S3_VAL:-$(rand_between 8 64)}\nS4_VAL=${S4_VAL:-$(rand_between 8 64)}\nH1_VAL=${H1_VAL:-$(rand_h_range)}\nH2_VAL=${H2_VAL:-$(rand_h_range)}\nH3_VAL=${H3_VAL:-$(rand_h_range)}\nH4_VAL=${H4_VAL:-$(rand_h_range)}\nwhile [ \"$H2_VAL\" = \"$H1_VAL\" ]; do H2_VAL=$(rand_h_range); done\nwhile [ \"$H3_VAL\" = \"$H1_VAL\" ] || [ \"$H3_VAL\" = \"$H2_VAL\" ]; do H3_VAL=$(rand_h_range); done\nwhile [ \"$H4_VAL\" = \"$H1_VAL\" ] || [ \"$H4_VAL\" = \"$H2_VAL\" ] || [ \"$H4_VAL\" = \"$H3_VAL\" ]; do H4_VAL=$(rand_h_range); done\nI1_VAL=${I1_VAL:-\"<r $(rand_between 2 6)><b 0x858000010001000000000669636c6f756403636f6d0000010001c00c000100010000105a00044d583737>\"}\nI2_VAL=${I2_VAL:-\"<r $(rand_between 3 8)><b 0x16030100><r $(rand_between 48 96)>\"}\nI3_VAL=${I3_VAL:-\"<r $(rand_between 6 12)><b 0x17030300><r $(rand_between 32 80)>\"}\nI4_VAL=${I4_VAL:-\"<r $(rand_between 4 10)><b 0x00000001><r $(rand_between 24 64)>\"}\nI5_VAL=${I5_VAL:-\"<r $(rand_between 8 14)><b 0x08000000><r $(rand_between 24 72)>\"}\n\nif ! command -v git >/dev/null 2>&1 || ! command -v curl >/dev/null 2>&1; then\n  apt-get update -qq\n  apt-get install -y -qq git curl ca-certificates >/dev/null 2>&1\nfi\n\nmkdir -p \"$HOST_CONFIG_DIR\"\n\nif [ ! -d \"$HOST_CONFIG_DIR/src/.git\" ]; then\n  rm -rf \"$HOST_CONFIG_DIR/src\"\n  git clone --depth=1 https://github.com/amnezia-vpn/amneziawg-go.git \"$HOST_CONFIG_DIR/src\"\nfi\n\n# Align the builder image with the Go version go.mod requires: upstream\n# pins an older golang tag in its Dockerfile and the build fails otherwise.\nGOVER=$(awk \'/^go /{print $2}\' \"$HOST_CONFIG_DIR/src/go.mod\" | cut -d. -f1,2)\nif [ -n \"$GOVER\" ] && [ -f \"$HOST_CONFIG_DIR/src/Dockerfile\" ]; then\n  sed -i -E \"s|^(FROM[[:space:]]+golang:)[0-9.]+|\\1${GOVER}|\" \"$HOST_CONFIG_DIR/src/Dockerfile\"\nfi\ndocker build --no-cache -t amnezia-awg2 \"$HOST_CONFIG_DIR/src\"\n\nEXISTING=$(docker ps -aq -f \"name=^/${CONTAINER_NAME}$\" 2>/dev/null | head -1 || true)\n\nif [ -z \"$EXISTING\" ]; then\n  docker run -d --name \"$CONTAINER_NAME\" --restart always --cap-add=NET_ADMIN --device /dev/net/tun -p \"${VPN_PORT}:${VPN_PORT}/udp\" -v \"${HOST_CONFIG_DIR}:${CONTAINER_CONFIG_DIR}\" amnezia-awg2 sh -c \"while [ ! -f ${CONTAINER_CONFIG_DIR}/${CONFIG_FILE} ]; do sleep 1; done; WG_QUICK_USERSPACE_IMPLEMENTATION=amneziawg-go awg-quick up ${CONTAINER_CONFIG_DIR}/${CONFIG_FILE} && sleep infinity\"\n  sleep 2\nelse\n  STATUS=$(docker inspect --format=\"{{.State.Status}}\" \"$CONTAINER_NAME\" 2>/dev/null || echo \"\")\n  if [ \"$STATUS\" != \"running\" ]; then\n    docker start \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\n  fi\nfi\n\nif [ -f \"${HOST_CONFIG_DIR}/${CONFIG_FILE}\" ]; then\n  PORT=$(grep -E \"^ListenPort\" \"${HOST_CONFIG_DIR}/${CONFIG_FILE}\" | cut -d= -f2 | tr -d \"[:space:]\" || true)\n  PSK=$(cat \"${HOST_CONFIG_DIR}/wireguard_psk.key\" 2>/dev/null || true)\n  PUBKEY=$(cat \"${HOST_CONFIG_DIR}/wireguard_server_public_key.key\" 2>/dev/null || true)\n\n  if [ -z \"${PUBKEY:-}\" ]; then\n    PRIVKEY=$(cat \"${HOST_CONFIG_DIR}/wireguard_server_private_key.key\" 2>/dev/null || true)\n    if [ -n \"$PRIVKEY\" ]; then\n      PUBKEY=$(echo \"$PRIVKEY\" | docker exec -i \"$CONTAINER_NAME\" awg pubkey)\n      echo \"$PUBKEY\" > \"${HOST_CONFIG_DIR}/wireguard_server_public_key.key\"\n    fi\n  fi\n\n  EXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\n  echo \"Using existing AmneziaWG 2.0 configuration\"\n  echo \"Port: ${PORT:-$VPN_PORT}\"\n  [ -n \"${PUBKEY:-}\" ] && echo \"Server Public Key: $PUBKEY\"\n  [ -n \"${PSK:-}\" ] && echo \"PresharedKey = $PSK\"\n  echo \"Server Host: $EXTERNAL_IP\"\n  echo \"Container Name: $CONTAINER_NAME\"\n\n  for P in Jc Jmin Jmax S1 S2 S3 S4 H1 H2 H3 H4 I1 I2 I3 I4 I5; do\n    VAL=$(grep -E \"^$P[[:space:]]*=\" \"${HOST_CONFIG_DIR}/${CONFIG_FILE}\" | cut -d= -f2- | sed \"s/^[[:space:]]*//;s/[[:space:]]*$//\" || true)\n    if [ -n \"$VAL\" ]; then\n      echo \"Variable: $P=$VAL\"\n    fi\n  done\n\n  echo \"Variable: dns_servers=1.1.1.1, 1.0.0.1\"\n  exit 0\nfi\n\nPRIVATE_KEY=\"${SERVER_PRIVATE_KEY:-$(docker exec \"$CONTAINER_NAME\" awg genkey)}\"\nPUBLIC_KEY=\"${SERVER_PUBLIC_KEY:-$(echo \"$PRIVATE_KEY\" | docker exec -i \"$CONTAINER_NAME\" awg pubkey)}\"\nPRESHARED_KEY=\"${SERVER_PRESHARED_KEY:-$(docker exec \"$CONTAINER_NAME\" awg genpsk)}\"\n\ncat > \"${HOST_CONFIG_DIR}/${CONFIG_FILE}\" << EOF\n[Interface]\nPrivateKey = $PRIVATE_KEY\nAddress = ${SERVER_ADDRESS:-10.8.1.1/24}\nListenPort = $VPN_PORT\nMTU = $MTU\nJc = $JC\nJmin = $JMIN\nJmax = $JMAX\nS1 = $S1_VAL\nS2 = $S2_VAL\nS3 = $S3_VAL\nS4 = $S4_VAL\nH1 = $H1_VAL\nH2 = $H2_VAL\nH3 = $H3_VAL\nH4 = $H4_VAL\nI1 = $I1_VAL\nI2 = $I2_VAL\nI3 = $I3_VAL\nI4 = $I4_VAL\nI5 = $I5_VAL\nPostUp = iptables -A FORWARD -i %i -j ACCEPT; iptables -A FORWARD -o %i -j ACCEPT; iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE\nPostDown = iptables -D FORWARD -i %i -j ACCEPT; iptables -D FORWARD -o %i -j ACCEPT; iptables -t nat -D POSTROUTING -o eth0 -j MASQUERADE\nEOF\n\nchmod 600 \"${HOST_CONFIG_DIR}/${CONFIG_FILE}\"\necho \"$PRIVATE_KEY\" > \"${HOST_CONFIG_DIR}/wireguard_server_private_key.key\"\necho \"$PUBLIC_KEY\" > \"${HOST_CONFIG_DIR}/wireguard_server_public_key.key\"\necho \"$PRESHARED_KEY\" > \"${HOST_CONFIG_DIR}/wireguard_psk.key\"\necho \"[]\" > \"${HOST_CONFIG_DIR}/clientsTable\"\n\ndocker restart \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\nsleep 2\n\nEXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\necho \"AmneziaWG 2.0 installed successfully\"\necho \"Port: $VPN_PORT\"\necho \"Server Public Key: $PUBLIC_KEY\"\necho \"PresharedKey = $PRESHARED_KEY\"\necho \"Server Host: $EXTERNAL_IP\"\necho \"Container Name: $CONTAINER_NAME\"\necho \"Variable: Jc=$JC\"\necho \"Variable: Jmin=$JMIN\"\necho \"Variable: Jmax=$JMAX\"\necho \"Variable: S1=$S1_VAL\"\necho \"Variable: S2=$S2_VAL\"\necho \"Variable: S3=$S3_VAL\"\necho \"Variable: S4=$S4_VAL\"\necho \"Variable: H1=$H1_VAL\"\necho \"Variable: H2=$H2_VAL\"\necho \"Variable: H3=$H3_VAL\"\necho \"Variable: H4=$H4_VAL\"\necho \"Variable: I1=$I1_VAL\"\necho \"Variable: I2=$I2_VAL\"\necho \"Variable: I3=$I3_VAL\"\necho \"Variable: I4=$I4_VAL\"\necho \"Variable: I5=$I5_VAL\"\necho \"Variable: dns_servers=1.1.1.1, 1.0.0.1\"','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-awg2}\"\n\ndocker stop \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker rm -fv \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker image rm amnezia-awg2 2>/dev/null || true\nrm -rf /opt/amnezia/awg2 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"AmneziaWG 2.0 uninstalled\"}\"',NULL,'[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = {{dns_servers}}\nMTU = 1280\nJc = {{Jc}}\nJmin = {{Jmin}}\nJmax = {{Jmax}}\nS1 = {{S1}}\nS2 = {{S2}}\nS3 = {{S3}}\nS4 = {{S4}}\nH1 = {{H1}}\nH2 = {{H2}}\nH3 = {{H3}}\nH4 = {{H4}}\nI1 = {{I1}}\nI2 = {{I2}}\nI3 = {{I3}}\nI4 = {{I4}}\nI5 = {{I5}}\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nAllowedIPs = 0.0.0.0/0, ::/0\nEndpoint = {{server_host}}:{{server_port}}\nPersistentKeepalive = 25',1,1,'2026-05-01 05:26:44','2026-07-10 10:39:40',NULL,'amnezia_compressed',0),(14,'Cloudflare WARP Egress','cf-warp','Cloudflare WARP client egress for AmneziaWG2 via a pool of WARP profiles (registered directly against the WARP API, no wgcf binary) with automatic rotation on error/429/traffic. Health-gated netns policy routing: AWG2 client TCP/UDP egress is routed through WARP only after a live trace check passes; the VPN handshake port stays direct and client configs are unchanged.','{\"engine\": \"shell\", \"metadata\": {\"mark\": \"0x2cf2\", \"warp_pool\": true, \"config_dir\": \"/opt/amnezia/awg2\", \"config_file\": \"awg0.conf\", \"route_table\": 51888, \"routing_scope\": \"tcp_udp_client_egress\", \"container_name\": \"amnezia-awg2\", \"routing_method\": \"warp_wireguard_netns_pool_rotation_health_gated\", \"target_protocol\": \"awg2\", \"routes_client_egress\": true, \"client_configs_unchanged\": true}}','#!/bin/bash\nset -euo pipefail\n\n# AWG2 Cloudflare WARP egress installer v3 (stored in protocols.install_script).\n# Deploys the v3 runtime (pool of WARP profiles + rotation), installs systemd\n# units, registers the pool, brings egress up, and health-gates the result.\n#\n# The runtime is embedded base64 (substituted at build time by\n# build_cf_warp_awg2_installer_v3.php).\n\nBIN=/usr/local/sbin/awg2-warp-egress\nSTATE_DIR=/var/lib/cloudflare-warp/awg2-egress\nRUNTIME_B64=\"\"\n\nexport DEBIAN_FRONTEND=noninteractive\nmkdir -p \"$STATE_DIR\" /etc/wireguard\n\n# 1. Write the runtime engine.\nprintf \'%s\' \"$RUNTIME_B64\" | base64 -d > \"$BIN\"\nchmod 0755 \"$BIN\"\n\n# 2. systemd units: the egress oneshot + a periodic health/rotation timer.\ncat > /etc/systemd/system/awg2-warp-egress.service <<UNIT\n[Unit]\nDescription=AWG2 Cloudflare WARP egress (pool + rotation)\nAfter=network-online.target docker.service\nWants=network-online.target\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=$BIN start\nExecStop=$BIN stop\nTimeoutStartSec=300\nRestart=no\n[Install]\nWantedBy=multi-user.target\nUNIT\n\ncat > /etc/systemd/system/awg2-warp-egress-health.service <<UNIT\n[Unit]\nDescription=AWG2 WARP egress health-check & rotation\nAfter=awg2-warp-egress.service\n[Service]\nType=oneshot\nExecStart=$BIN health\nUNIT\n\ncat > /etc/systemd/system/awg2-warp-egress-health.timer <<UNIT\n[Unit]\nDescription=Run AWG2 WARP egress health-check periodically\n[Timer]\nOnBootSec=2min\nOnUnitInactiveSec=${WARP_HEALTH_INTERVAL:-60s}\nAccuracySec=10s\n[Install]\nWantedBy=timers.target\nUNIT\n\nsystemctl daemon-reload\n\n# 3. Register the profile pool up front (so start is fast and health-gated).\n\"$BIN\" register || true\n\n# 4. Enable + start egress, then the health timer.\nsystemctl enable awg2-warp-egress.service >/dev/null 2>&1 || true\nif ! systemctl restart awg2-warp-egress.service; then\n  echo \"Variable: warp_status=start_failed\"\n  journalctl -u awg2-warp-egress.service -n 20 --no-pager 2>/dev/null || true\n  exit 20\nfi\nsystemctl enable awg2-warp-egress-health.timer >/dev/null 2>&1 || true\nsystemctl start awg2-warp-egress-health.timer >/dev/null 2>&1 || true\n\n# 5. Health gate: confirm WARP is actually on before declaring success.\nok=0\nfor i in $(seq 1 8); do\n  trace=\"$(ip netns exec awg2warp curl -4 -s --max-time 6 --resolve cloudflare.com:443:104.16.132.229 https://cloudflare.com/cdn-cgi/trace 2>/dev/null || true)\"\n  if echo \"$trace\" | grep -q \'^warp=on$\'; then ok=1; break; fi\n  sleep 3\ndone\n\nwarp_ip=\"$(ip netns exec awg2warp curl -4 -s --max-time 6 --resolve cloudflare.com:443:104.16.132.229 https://cloudflare.com/cdn-cgi/trace 2>/dev/null | awk -F= \'$1==\"ip\"{print $2; exit}\' || true)\"\nactive=\"$(cat \"$STATE_DIR/active\" 2>/dev/null || echo \'\')\"\npool=\"$(find \"$STATE_DIR/profiles\" -mindepth 2 -maxdepth 2 -name profile.setconf 2>/dev/null | wc -l | tr -d \' \')\"\n\necho \"Variable: warp_mode=wireguard_netns_pool_rotating\"\necho \"Variable: warp_pool_size=$pool\"\necho \"Variable: warp_active_profile=$active\"\necho \"Variable: warp_ip=${warp_ip:-unknown}\"\nif [ \"$ok\" = \"1\" ]; then\n  echo \"Variable: warp_status=on\"\n  echo \"AWG2 WARP egress installed and connected (pool=$pool, active=$active, exit=$warp_ip)\"\nelse\n  echo \"Variable: warp_status=unhealthy\"\n  echo \"AWG2 WARP egress installed but WARP did not come up healthy\"\n  exit 21\nfi\n','#!/bin/bash\nset +e\n\n# AWG2 Cloudflare WARP egress uninstaller v3 (stored in protocols.uninstall_script).\n# Tears down the systemd units, the netns/routing runtime, and local state.\n\nBIN=/usr/local/sbin/awg2-warp-egress\nSTATE_DIR=/var/lib/cloudflare-warp/awg2-egress\n\nsystemctl stop awg2-warp-egress-health.timer 2>/dev/null\nsystemctl disable awg2-warp-egress-health.timer 2>/dev/null\nsystemctl stop awg2-warp-egress.service 2>/dev/null\nsystemctl disable awg2-warp-egress.service 2>/dev/null\nsystemctl reset-failed awg2-warp-egress.service 2>/dev/null\n\n# Runtime teardown (netns, veth, mangle chain, policy routing).\nif [ -x \"$BIN\" ]; then\n  \"$BIN\" cleanup 2>/dev/null\nfi\n\n# Belt-and-suspenders removal in case the engine binary is already gone.\nNS=awg2warp; VETH=awg2warp0; TABLE=51888; MARK=0x2cf2; CHAIN=AWG2_WARP_EGRESS\nfor ip in $(cat \"$STATE_DIR/container_ips\" 2>/dev/null); do\n  while iptables -t mangle -D PREROUTING -s \"$ip/32\" -j \"$CHAIN\" 2>/dev/null; do :; done\ndone\nwhile iptables -D FORWARD -i \"$VETH\" -o eth0 -j ACCEPT 2>/dev/null; do :; done\nwhile iptables -D FORWARD -i eth0 -o \"$VETH\" -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT 2>/dev/null; do :; done\nwhile iptables -t nat -D POSTROUTING -s 10.255.0.0/30 -o eth0 -j MASQUERADE 2>/dev/null; do :; done\niptables -t mangle -F \"$CHAIN\" 2>/dev/null\niptables -t mangle -X \"$CHAIN\" 2>/dev/null\nwhile ip rule del fwmark \"$MARK\" table \"$TABLE\" 2>/dev/null; do :; done\nip route flush table \"$TABLE\" 2>/dev/null\nip link del \"$VETH\" 2>/dev/null\nip netns del \"$NS\" 2>/dev/null\n\nrm -f /etc/systemd/system/awg2-warp-egress.service \\\n      /etc/systemd/system/awg2-warp-egress-health.service \\\n      /etc/systemd/system/awg2-warp-egress-health.timer\nsystemctl daemon-reload 2>/dev/null\n\nrm -f \"$BIN\" /etc/wireguard/awg2-warp-egress.setconf\nrm -rf \"/etc/netns/$NS\" \"$STATE_DIR\"\n\necho \"WARP_UNINSTALL_DONE\"\n',NULL,'WARP client egress for AmneziaWG2 (pool + rotation)\nMode: {{warp_mode}}\nActive profile: {{warp_active_profile}}\nPool size: {{warp_pool_size}}\nRotations: {{warp_rotations}}\nExit IP: {{warp_ip}}\nStatus: {{warp_status}}\n',1,1,'2026-05-01 05:26:45','2026-07-10 09:41:18',NULL,'amnezia_compressed',1);
